<?php
declare(strict_types=1);

// Banco de preguntas y carga masiva por CSV.
// Permite crear, revisar y publicar preguntas para uso en práctica y simulacros.
require __DIR__.'/../includes/auth.php';require_login();require_once __DIR__.'/../config/database.php';csrf_check();
$me=$_SESSION['user'];$uid=(int)$me['id'];$role=(string)$me['role'];if(!in_array($role,['teacher','admin','superadmin'],true)){http_response_code(403);exit('Solo docentes y administradores.');}
$flash='';$preview=$_SESSION['question_import_preview']??null;
function save_question(PDO $pdo,int $author,array $row,?int $questionId=null): int {
 if(!isset($row['area'])&&(int)($row['topic_id']??0)>0){$base=$pdo->prepare('SELECT t.name topic,t.grade_level,s.name area,c.name competencia FROM topics t JOIN academic_competencies c ON c.id=t.competency_id JOIN subjects s ON s.id=c.subject_id WHERE t.id=?');$base->execute([(int)$row['topic_id']]);$details=$base->fetch();if(!$details)throw new RuntimeException('Selecciona un tema válido.');$row=array_merge($row,$details);$row['grado']=$details['grade_level'];}
 $area=trim((string)$row['area']);$competency=trim((string)$row['competencia']);$topic=trim((string)$row['tema']);$grade=(int)$row['grado'];$difficulty=(int)$row['dificultad'];$prompt=trim((string)$row['enunciado']);$correct=strtoupper(trim((string)$row['respuesta']));$explanation=trim((string)$row['explicacion']);$source=trim((string)($row['fuente']??'Contenido original del docente'));
 if($grade<5||$grade>11||$difficulty<1||$difficulty>5||mb_strlen($prompt)<5||mb_strlen($prompt)>5000||mb_strlen($explanation)<3||mb_strlen($source)>190||!in_array($correct,['A','B','C','D'],true))throw new RuntimeException('Campos inválidos en la pregunta.');
 $options=[];foreach(['A','B','C','D'] as $label){$key='opcion_'.strtolower($label);$val=trim((string)($row[$key]??''));if($val===''||mb_strlen($val)>2000)throw new RuntimeException('Cada pregunta necesita cuatro opciones válidas.');$options[$label]=$val;}
 $s=$pdo->prepare('SELECT id FROM subjects WHERE name=?');$s->execute([$area]);$sid=$s->fetchColumn();if(!$sid)throw new RuntimeException('Asignatura no reconocida: '.$area);
 $c=$pdo->prepare('SELECT id FROM academic_competencies WHERE subject_id=? AND name=?');$c->execute([$sid,$competency]);$cid=$c->fetchColumn();if(!$cid)throw new RuntimeException('Competencia no reconocida para '.$area.': '.$competency);
 $t=$pdo->prepare('SELECT id FROM topics WHERE competency_id=? AND name=? AND grade_level=?');$t->execute([$cid,$topic,$grade]);$tid=$t->fetchColumn();if(!$tid){$pdo->prepare('INSERT INTO topics(competency_id,name,grade_level) VALUES(?,?,?)')->execute([$cid,$topic,$grade]);$tid=(int)$pdo->lastInsertId();}
 if($questionId){$has=$pdo->prepare('SELECT q.review_status,EXISTS(SELECT 1 FROM activity_attempts a WHERE a.question_id=q.id) OR EXISTS(SELECT 1 FROM diagnostic_answers d WHERE d.question_id=q.id) OR EXISTS(SELECT 1 FROM exam_answers e WHERE e.question_id=q.id) attempted FROM questions q WHERE q.id=?');$has->execute([$questionId]);$old=$has->fetch();if(!$old)throw new RuntimeException('Pregunta no encontrada.');if($old['review_status']==='approved'&&$old['attempted'])throw new RuntimeException('No se edita una pregunta publicada con intentos históricos; duplica y crea otra versión.');$pdo->prepare('UPDATE questions SET topic_id=?,grade_level=?,prompt=?,answer_key=?,explanation=?,difficulty=?,source=?,review_status=\'draft\' WHERE id=?')->execute([$tid,$grade,$prompt,$correct,$explanation,$difficulty,$source,$questionId]);$pdo->prepare('DELETE FROM question_options WHERE question_id=?')->execute([$questionId]);$qid=$questionId;
 }else{$dupe=$pdo->prepare('SELECT id FROM questions WHERE topic_id=? AND prompt=? LIMIT 1');$dupe->execute([$tid,$prompt]);if($dupe->fetchColumn())throw new RuntimeException('Pregunta duplicada para este tema.');$pdo->prepare("INSERT INTO questions(topic_id,grade_level,type,prompt,answer_key,explanation,difficulty,source,review_status) VALUES(?,?,'single_choice',?,?,?,?,?,'draft')")->execute([$tid,$grade,$prompt,$correct,$explanation,$difficulty,$source]);$qid=(int)$pdo->lastInsertId();}
 foreach($options as $label=>$body)$pdo->prepare('INSERT INTO question_options(question_id,label,body) VALUES(?,?,?)')->execute([$qid,$label,$body]);$pdo->prepare('INSERT INTO question_authors(question_id,author_id) VALUES(?,?) ON DUPLICATE KEY UPDATE author_id=VALUES(author_id)')->execute([$qid,$author]);$tags=trim((string)($row['tags']??''));foreach(array_slice(array_filter(array_map('trim',explode('|',$tags))),0,10) as $tag){if(mb_strlen($tag)<=60)$pdo->prepare('INSERT IGNORE INTO question_tags(question_id,tag) VALUES(?,?)')->execute([$qid,$tag]);}return $qid;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');
 try{
  if($action==='question_save'){$row=$_POST;$pdo->beginTransaction();try{$qid=save_question($pdo,$uid,$row,((int)($_POST['question_id']??0))?:null);audit_event($pdo,$uid,'question.saved',['question_id'=>$qid]);$pdo->commit();$flash='Pregunta guardada como borrador.';}catch(Throwable $e){$pdo->rollBack();throw $e;}}
  elseif($action==='question_publish'&&in_array($role,['admin','superadmin'],true)){$qid=(int)($_POST['question_id']??0);$q=$pdo->prepare("UPDATE questions SET review_status=IF(review_status='approved','draft','approved') WHERE id=?");$q->execute([$qid]);audit_event($pdo,$uid,'question.publication_changed',['question_id'=>$qid]);$flash='Estado de publicación cambiado.';}
  elseif($action==='csv_preview'){$f=$_FILES['csv']??[];if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||(int)$f['size']>1024*1024||!is_uploaded_file((string)$f['tmp_name']))throw new RuntimeException('Elige un CSV de hasta 1 MB.');$handle=fopen($f['tmp_name'],'rb');$header=fgetcsv($handle,0,',','"','\\');if(!$header)throw new RuntimeException('El CSV está vacío.');$header[0]=preg_replace('/^\xEF\xBB\xBF/','',(string)$header[0]);$expected=['area','competencia','tema','grado','dificultad','enunciado','opcion_a','opcion_b','opcion_c','opcion_d','respuesta','explicacion','fuente','tags'];if(array_map('strtolower',$header)!==$expected){fclose($handle);throw new RuntimeException('Las columnas no coinciden con la plantilla descargable.');}$rows=[];$seen=[];$line=1;while(($values=fgetcsv($handle,0,',','"','\\'))!==false){$line++;if(count($values)!==count($expected)){$rows[]=['line'=>$line,'error'=>'Cantidad de columnas incorrecta'];continue;}$row=array_combine($expected,$values);$row['grado']=(int)$row['grado'];$row['dificultad']=(int)$row['dificultad'];$problem='';try{$area=$pdo->prepare('SELECT id FROM subjects WHERE name=?');$area->execute([trim($row['area'])]);$sid=$area->fetchColumn();$comp=$pdo->prepare('SELECT id FROM academic_competencies WHERE subject_id=? AND name=?');$comp->execute([$sid,trim($row['competencia'])]);$cid=$comp->fetchColumn();if(!$sid||!$cid)throw new RuntimeException('Área/competencia no existe.');if($row['grado']<5||$row['grado']>11||$row['dificultad']<1||$row['dificultad']>5||mb_strlen(trim($row['tema']))<2||mb_strlen(trim($row['enunciado']))<5||mb_strlen(trim($row['enunciado']))>5000||!in_array(strtoupper(trim($row['respuesta'])),['A','B','C','D'],true)||trim($row['explicacion'])===''||array_filter([$row['opcion_a'],$row['opcion_b'],$row['opcion_c'],$row['opcion_d']],fn($x)=>trim($x)===''))throw new RuntimeException('Faltan campos o los valores están fuera de rango.');$finger=hash('sha256',mb_strtolower(trim($row['area'].'|'.$row['competencia'].'|'.$row['tema'].'|'.$row['grado'].'|'.$row['enunciado'])));if(isset($seen[$finger]))throw new RuntimeException('Duplicada en el mismo archivo (fila '.$seen[$finger].').');$seen[$finger]=$line;$topic=$pdo->prepare('SELECT id FROM topics WHERE competency_id=? AND name=? AND grade_level=?');$topic->execute([$cid,trim($row['tema']),$row['grado']]);$tid=$topic->fetchColumn();if($tid){$dup=$pdo->prepare('SELECT id FROM questions WHERE topic_id=? AND prompt=?');$dup->execute([$tid,trim($row['enunciado'])]);if($dup->fetchColumn())throw new RuntimeException('Ya existe en el banco.');}$rows[]=['line'=>$line,'row'=>$row,'valid'=>true];}catch(Throwable $e){$rows[]=['line'=>$line,'row'=>$row,'error'=>$e->getMessage()];}if(count($rows)>=200)break;}fclose($handle);$_SESSION['question_import_preview']=$rows;$preview=$rows;$flash='Vista previa lista. Confirma para guardar solo las filas válidas.';}
  elseif($action==='csv_import'){$rows=$_SESSION['question_import_preview']??[];$pdo->beginTransaction();$created=0;$skipped=0;$errors=[];try{foreach($rows as $r){if(empty($r['valid'])){$skipped++;continue;}try{save_question($pdo,$uid,$r['row']);$created++;}catch(Throwable $e){$skipped++;$errors[]='Fila '.(int)$r['line'].': '.$e->getMessage();}}$pdo->prepare('INSERT INTO question_imports(user_id,created_count,skipped_count,errors) VALUES(?,?,?,?)')->execute([$uid,$created,$skipped,$errors?json_encode($errors,JSON_UNESCAPED_UNICODE):null]);audit_event($pdo,$uid,'question.csv_imported',['created'=>$created,'skipped'=>$skipped]);$pdo->commit();unset($_SESSION['question_import_preview']);$preview=null;$flash="Importadas: {$created}; omitidas: {$skipped}.";}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
  elseif($action==='question_archive'){$qid=(int)($_POST['question_id']??0);if($role==='admin'){$q=$pdo->prepare("UPDATE questions SET review_status='draft' WHERE id=?");$q->execute([$qid]);}else{$q=$pdo->prepare("UPDATE questions SET review_status='draft' WHERE id=? AND EXISTS(SELECT 1 FROM question_authors qa WHERE qa.question_id=questions.id AND qa.author_id=?)");$q->execute([$qid,$uid]);}$pdo->prepare('UPDATE question_authors SET archived_at=NOW() WHERE question_id=? AND author_id=?')->execute([$qid,$uid]);$flash='Pregunta retirada del banco publicado.';}
 }catch(Throwable $e){$flash=$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar. Revisa las columnas, opciones y migración.';}
}
$topics=$pdo->query('SELECT t.id,t.name topic,t.grade_level,s.name subject,c.name competency FROM topics t JOIN academic_competencies c ON c.id=t.competency_id JOIN subjects s ON s.id=c.subject_id ORDER BY s.name,t.grade_level,t.name')->fetchAll();
$sql='SELECT q.id,q.prompt,q.grade_level,q.difficulty,q.review_status,s.name subject,c.name competency,t.name topic FROM questions q JOIN topics t ON t.id=q.topic_id JOIN academic_competencies c ON c.id=t.competency_id JOIN subjects s ON s.id=c.subject_id';if($role!=='admin')$sql.=' JOIN question_authors qa ON qa.question_id=q.id AND qa.author_id='.(int)$uid;$sql.=' ORDER BY q.created_at DESC LIMIT 100';$questions=$pdo->query($sql)->fetchAll();
if(($_GET['plantilla']??'')==='1'&&$_SERVER['REQUEST_METHOD']==='GET'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="plantilla-preguntas.csv"');$out=fopen('php://output','wb');fputcsv($out,['area','competencia','tema','grado','dificultad','enunciado','opcion_a','opcion_b','opcion_c','opcion_d','respuesta','explicacion','fuente','tags']);fclose($out);exit;}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Banco de preguntas · Prossor AI</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="app-body"><main class="main-content"><header class="topbar"><a href="dashboard.php">← Mi espacio</a><b>Banco de preguntas</b></header><?php if($flash): ?><div class="notice flash"><?= h($flash) ?></div><?php endif; ?><section class="panel"><h2>Crear pregunta de selección única</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label>Área / competencia / tema<select name="topic_id" required><?php foreach($topics as $t): ?><option value="<?= (int)$t['id'] ?>"><?= h($t['subject'].' · '.$t['competency'].' · '.$t['topic'].' · Grado '.$t['grade_level']) ?></option><?php endforeach; ?></select></label><label>Enunciado<textarea name="enunciado" maxlength="5000" required></textarea></label><?php foreach(['a','b','c','d'] as $letter): ?><label>Opción <?= strtoupper($letter) ?><input name="opcion_<?= $letter ?>" maxlength="2000" required></label><?php endforeach; ?><label>Respuesta correcta<select name="respuesta"><option>A</option><option>B</option><option>C</option><option>D</option></select></label><label>Explicación<textarea name="explicacion" maxlength="5000" required></textarea></label><label>Dificultad<select name="dificultad"><?php for($i=1;$i<=5;$i++): ?><option value="<?= $i ?>"><?= $i ?></option><?php endfor; ?></select></label><label>Fuente opcional<input name="fuente" maxlength="190"></label><label>Etiquetas separadas por |<input name="tags" maxlength="500"></label><button class="button primary" name="action" value="question_save">Guardar borrador</button></form></section>
<section class="panel"><h2>Importar CSV</h2><p>Columnas exactas: area, competencia, tema, grado, dificultad, enunciado, opcion_a, opcion_b, opcion_c, opcion_d, respuesta, explicacion, fuente, tags. Las opciones deben ser inequívocas; respuestas A-D. Máximo 200 filas y 1 MB.</p><a class="button light" href="preguntas.php?plantilla=1">Descargar plantilla</a><form method="post" enctype="multipart/form-data" class="chat-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="file" name="csv" accept=".csv,text/csv" required><button class="button light" name="action" value="csv_preview">Previsualizar</button></form>
<?php if($preview): ?><div class="table-wrap"><table><thead><tr><th>Fila</th><th>Enunciado</th><th>Validación</th></tr></thead><tbody><?php foreach($preview as $r): ?><tr><td><?= (int)$r['line'] ?></td><td><?= h((string)($r['row']['enunciado']??'')) ?></td><td><?= !empty($r['valid'])?'Lista para importar':h((string)($r['error']??'Inválida')) ?></td></tr><?php endforeach; ?></tbody></table></div><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><button class="button primary" name="action" value="csv_import">Confirmar importación</button></form><?php endif; ?></section>
<section class="panel"><h2>Banco reciente</h2><div class="table-wrap"><table><thead><tr><th>Área</th><th>Grado</th><th>Tema</th><th>Pregunta</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($questions as $q): ?><tr><td><?= h($q['subject']) ?> · <?= h($q['competency']) ?></td><td><?= (int)$q['grade_level'] ?></td><td><?= h($q['topic']) ?></td><td><?= h(mb_strimwidth($q['prompt'],0,90,'…')) ?></td><td><?= h($q['review_status']) ?></td><td><?php if($role==='admin'): ?><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="question_id" value="<?= (int)$q['id'] ?>"><button class="mini-button" name="action" value="question_publish"><?= $q['review_status']==='approved'?'Retirar':'Aprobar' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section></main></body></html>
